const recipes = [
  { id: 1, title: "Tomato soup", minutes: 30, difficulty: "medium", rating: 4, ingredients: ["tomatoes", "onion", "basil"] },
  { id: 2, title: "Garlic bread", minutes: 15, difficulty: "medium", rating: 5, ingredients: ["bread", "garlic", "butter"] },
  { id: 3, title: "Lemon pasta", minutes: 20, difficulty: "medium", rating: 3, ingredients: ["pasta", "lemon", "cheese"] },
];
let nextId = 4;

export function loadRecipes() {
  return new Promise((resolve) => setTimeout(() => resolve(recipes), 30));
}

export function loadRecipe(id) {
  return new Promise((resolve) =>
    setTimeout(() => resolve(recipes.find((r) => r.id === id) ?? null), 30),
  );
}

export function addRecipe({ title, minutes, difficulty = "medium" }) {
  const recipe = { id: nextId++, title, minutes, difficulty, rating: 0, ingredients: [] };
  recipes.push(recipe);
  return recipe;
}

import { addRecipe } from "../../../store.js";

export const POST = Run.POST(async (context) => {
  const form = await context.request.formData();
  const title = String(form.get("title") || "").trim();
  const minutes = Number(form.get("minutes")) || 0;
  const difficulty = String(form.get("difficulty") || "medium").trim();
  if (!title) return context.redirect("/recipes/new", 303);
  const recipe = addRecipe({ title, minutes, difficulty });
  return context.redirect(`/recipes/${recipe.id}`, 303);
});

